"""Bot perception: what a server-controlled bot is allowed to know.

A bot perceives an opponent only when it is within the profile's view distance, inside the view
cone around the bot's yaw, and in line of sight past map blockers. A bot that was just shot may
also locate its attacker regardless of the cone (it heard and felt the shot), still only within
range and line of sight. Loot is visible within LOOT_SIGHT metres with line of sight.

The blocker and loot indexes live in `app.game.solo.spatial` and are shared with combat, views
and maps; `BlockerIndex`, `LootIndex` and `blocker_index` are re-exported here.
`MatchMemory` holds the match's shared loot index and the damage-event cursor. It is keyed by
the match object's identity and dropped by `forget` or when the match is garbage collected.

Range is 3D (altitude included) and the perceivable life states are combat's SHOOTABLE set, so
bots and humans follow the same targeting rules. The event cursor is absolute
(`match.events_base` + index) and is published as a hold in `match.event_holds`, so the engine
keeps events emitted after the bot driver ran until the bots have absorbed them.
"""

import math
import weakref
from dataclasses import dataclass, field

from solo_engine import spatial
from solo_engine.combat import SHOOTABLE
from solo_engine.geometry import SpatialGrid
from solo_engine.model import BotState, LifeState, MatchEvent, Participant, SoloMatch
from solo_engine.spatial import BlockerIndex, LootIndex, blocker_index

__all__ = ["BlockerIndex", "LootIndex", "blocker_index"]  # re-exported from spatial

LOOT_SIGHT = 40.0  # metres a bot can see ground loot
ATTACKER_MEMORY = 3.0  # seconds a hit lets the bot locate its attacker outside its view cone
ATTACKER_RANGE_FACTOR = 1.5  # x view distance within which a recent attacker can be located
TRACK_RANGE_FACTOR = 1.2  # x view distance within which an acquired target stays tracked
ALWAYS_SEEN = 2.0  # metres: anything this close is noticed whatever the yaw
NEW_ENGAGEMENT_GAP = 3.0  # seconds without damage after which a hit counts as a new engagement
# Bots perceive exactly the life states combat lets anyone shoot (humans and bots, same rules).
PERCEIVABLE = SHOOTABLE
EVENT_HOLD = "bots"  # key in match.event_holds
_NO_COVER_STATES = frozenset({BotState.WAITING, BotState.AIRCRAFT, BotState.PARACHUTING, BotState.ELIMINATED})

# --------------------------------------------------------------------------- per-match memory


@dataclass
class MatchMemory:
    loot: LootIndex = field(default_factory=LootIndex)
    landing_picks: dict[str, int] = field(default_factory=dict)  # POI name -> bots that chose it
    landing_points: list[tuple[float, float]] = field(default_factory=list)  # chosen targets
    cursor: int = 0  # absolute event sequence number of the next event to absorb


_MEMORY: dict[int, MatchMemory] = {}


def memory(match: SoloMatch) -> MatchMemory:
    """Bot-side memory for one match, released when the match object is collected."""
    key = id(match)
    mem = _MEMORY.get(key)
    if mem is None:
        mem = MatchMemory(loot=spatial.loot_index(match))
        _MEMORY[key] = mem
        weakref.finalize(match, _MEMORY.pop, key, None)
    return mem


def forget(match: SoloMatch) -> None:
    """Drop bot memory for a match now (optional; collection does it too)."""
    _MEMORY.pop(id(match), None)
    match.event_holds.pop(EVENT_HOLD, None)


def _new_events(match: SoloMatch, mem: MatchMemory) -> list[MatchEvent]:
    """Events not yet absorbed, each returned exactly once.

    `mem.cursor` is an absolute event sequence number (`match.events_base` + index). The bot
    hold in `match.event_holds` tells the engine not to trim events the bots have not read, so
    events emitted after the bot driver ran (bot fire, grenades, zone) are seen next tick.
    """
    events = match.events
    start = min(max(mem.cursor - match.events_base, 0), len(events))
    fresh = events[start:]
    mem.cursor = match.events_base + len(events)
    match.event_holds[EVENT_HOLD] = mem.cursor
    return fresh


def absorb_damage_events(match: SoloMatch, mem: MatchMemory) -> None:
    """Let each bot that was hit by a participant remember when and by whom.

    A hit that starts a new engagement rolls the bot's cover chance once; on success the bot's
    state becomes TAKING_COVER and the controller picks a cover point at its next decision,
    which is brought forward by half the bot's reaction time.
    """
    for event in _new_events(match, mem):
        if event.kind != "damage":
            continue
        victim = match.participants.get(event.data.get("victim_id") or "")
        attacker_id = event.data.get("attacker_id")
        if victim is None or victim.brain is None or not attacker_id or attacker_id == victim.participant_id:
            continue
        if not victim.alive:
            continue
        brain = victim.brain
        new_engagement = brain.last_damaged_at < 0 or event.at - brain.last_damaged_at > NEW_ENGAGEMENT_GAP
        brain.last_damaged_at = event.at
        brain.last_attacker_id = attacker_id
        brain.next_decision_at = min(brain.next_decision_at, event.at + brain.profile.reaction_time * 0.5)
        if (
            new_engagement
            and victim.life == LifeState.GROUNDED
            and brain.state not in _NO_COVER_STATES
            and match.rng.random() < brain.profile.cover_chance
        ):
            brain.state = BotState.TAKING_COVER
            brain.destination = None
            brain.path.clear()


# --------------------------------------------------------------------------- opponents


def can_see(
    index: BlockerIndex,
    observer: Participant,
    other: Participant,
    max_distance: float,
    fov_degrees: float | None,
) -> bool:
    """Range, optional view cone around observer.yaw, and line of sight."""
    if other is observer or not other.alive or other.life not in PERCEIVABLE:
        return False
    dx = other.x - observer.x
    dy = other.y - observer.y
    dz = other.z - observer.z
    d2 = dx * dx + dy * dy
    if d2 + dz * dz > max_distance * max_distance:  # range is 3D, like combat
        return False
    if fov_degrees is not None and d2 > ALWAYS_SEEN * ALWAYS_SEEN:
        d = math.sqrt(d2)
        facing = (math.cos(observer.yaw) * dx + math.sin(observer.yaw) * dy) / d
        if facing < math.cos(math.radians(fov_degrees) / 2.0):
            return False
    return index.los(observer.x, observer.y, other.x, other.y)


def recently_hit_by(observer: Participant, now: float) -> str | None:
    brain = observer.brain
    if brain is None or brain.last_damaged_at < 0 or now - brain.last_damaged_at > ATTACKER_MEMORY:
        return None
    return brain.last_attacker_id


def visible_opponents(
    match: SoloMatch, grid: SpatialGrid, index: BlockerIndex, bot: Participant, now: float
) -> list[Participant]:
    """Opponents the bot perceives now, nearest first (ties by id). Uses the spatial grid."""
    profile = bot.brain.profile
    view = profile.view_distance
    attacker_id = recently_hit_by(bot, now)
    radius = view * ATTACKER_RANGE_FACTOR if attacker_id else view
    seen: list[tuple[float, str, Participant]] = []
    for other_id in grid.near(bot.x, bot.y, radius):
        if other_id == bot.participant_id:
            continue
        other = match.participants.get(other_id)
        if other is None:
            continue
        if other_id == attacker_id:
            ok = can_see(index, bot, other, view * ATTACKER_RANGE_FACTOR, None)
        else:
            ok = can_see(index, bot, other, view, profile.view_fov_degrees)
        if ok:
            seen.append(((other.x - bot.x) ** 2 + (other.y - bot.y) ** 2, other_id, other))
    seen.sort(key=lambda entry: (entry[0], entry[1]))
    return [entry[2] for entry in seen]


def can_track(index: BlockerIndex, bot: Participant, target: Participant) -> bool:
    """An acquired target stays perceived while in tracking range and line of sight."""
    return can_see(index, bot, target, bot.brain.profile.view_distance * TRACK_RANGE_FACTOR, None)
